inputs = ['jykdi', 'uzwxu', 'af', 'gwhk', 'gcxb']
outputs = ['jykdi', 'uzkubcubu', 'ff', 'gkhk', 'gcubcubfe']

rules = [("a", "f"), ("wx", "kubcub"), ("xb", "ubcubfe")]

print("Full test with rules:", rules)
result = []
for inp in inputs:
    out = inp
    for pattern, replacement in rules:
        out = out.replace(pattern, replacement)
    result.append(out)

for i, inp in enumerate(inputs):
    print(f"'{inp}' -> '{result[i]}' (expected '{outputs[i]}')")

print("\nChecking for mismatches:")
for i in range(len(inputs)):
    if result[i] != outputs[i]:
        print(f"Index {i}: got '{result[i]}', expected '{outputs[i]}'")

